library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all; library std; use std.env.all;
entity tb_bbq_add_sub_core is end; architecture sim of tb_bbq_add_sub_core is signal a,b,r:std_logic_vector(7 downto 0);signal sub,c,o,z,n:std_logic;begin dut:entity work.bbq_add_sub_core generic map(WIDTH=>8,SIGNED_MODE=>false)port map(a=>a,b=>b,subtract=>sub,result=>r,carry_borrow=>c,overflow=>o,zero=>z,negative=>n);process begin a<=x"FA";b<=x"0A";sub<='0';wait for 1 ns;assert r=x"04" and c='1' severity failure;sub<='1';wait for 1 ns;assert r=x"F0" and c='0' severity failure;report "PASS" severity note;stop;wait;end process;end;
